import math
from fastapi import APIRouter, Depends, Body
from fastapi.responses import JSONResponse
from starlette.middleware.base import BaseHTTPMiddleware
from services.db import connect
from shared.constants.categories import CategoryEnum
from backend.services.calculations import calculate_recurring_transactions, calculate_leak_finder, calculate_budget_drift

router = APIRouter(prefix="/tracker")

class TrackerSpecialist:
    def __init__(self, llm_client):
        self.llm_client = llm_client

    def detect_recurring_transactions(self, transactions):
        return calculate_recurring_transactions(transactions)

    def find_leak_finder(self, transactions):
        return calculate_leak_finder(transactions)

    def detect_budget_drift(self, transactions):
        return calculate_budget_drift(transactions)

@router.get("/transactions")
async def get_transactions(date_range: dict = Body(default={}), category: CategoryEnum = Body(default=None), account: str = Body(default=None)):
    conn = connect()
    try:
        transactions = conn.execute("SELECT * FROM transactions WHERE date BETWEEN ? AND ?", (date_range['start'], date_range['end'])).fetchall()
        if category:
            transactions = [t for t in transactions if t['category'] == category.value]
        if account:
            transactions = [t for t in transactions if t['account'] == account]
        return JSONResponse(content={"state": "ok", "transactions": transactions})
    finally:
        conn.close()

@router.get("/transactions/{id}")
async def get_transaction(id: int):
    conn = connect()
    try:
        transaction = conn.execute("SELECT * FROM transactions WHERE id = ?", (id,)).fetchone()
        if transaction:
            return JSONResponse(content={"state": "ok", "transaction": transaction})
        else:
            return JSONResponse(content={"state": "not_found"}, status_code=404)
    finally:
        conn.close()

@router.put("/transactions/{id}")
async def update_transaction(id: int, amount: float):
    conn = connect()
    try:
        conn.execute("UPDATE transactions SET amount = ? WHERE id = ?", (amount, id))
        conn.commit()
        return JSONResponse(content={"state": "ok"})
    finally:
        conn.close()

@router.delete("/transactions/{id}")
async def delete_transaction(id: int):
    conn = connect()
    try:
        conn.execute("DELETE FROM transactions WHERE id = ?", (id,))
        conn.commit()
        return JSONResponse(content={"state": "ok"})
    finally:
        conn.close()

@router.get("/categories")
async def get_categories():
    conn = connect()
    try:
        categories = conn.execute("SELECT category, SUM(amount) as total FROM transactions GROUP BY category").fetchall()
        return JSONResponse(content={"state": "ok", "categories": categories})
    finally:
        conn.close()

@router.get("/recurring")
async def get_recurring_transactions():
    conn = connect()
    try:
        transactions = conn.execute("SELECT * FROM transactions").fetchall()
        specialist = TrackerSpecialist(llm_client=None)
        recurring_transactions = specialist.detect_recurring_transactions(transactions)
        return JSONResponse(content={"state": "ok", "recurring_transactions": recurring_transactions})
    finally:
        conn.close()

@router.get("/trends")
async def get_monthly_trends():
    conn = connect()
    try:
        trends = conn.execute("SELECT date, SUM(amount) as total FROM transactions GROUP BY date").fetchall()
        return JSONResponse(content={"state": "ok", "trends": trends})
    finally:
        conn.close()

@router.get("/insights")
async def get_insights():
    conn = connect()
    try:
        transactions = conn.execute("SELECT * FROM transactions").fetchall()
        specialist = TrackerSpecialist(llm_client=None)
        leak_finder = specialist.find_leak_finder(transactions)
        budget_drift = specialist.detect_budget_drift(transactions)
        insight = f"Leak of the week: {leak_finder['category']} with a delta of {leak_finder['delta']}. Budget drift: {budget_drift}%."
        return JSONResponse(content={"state": "ok", "insight": insight})
    finally:
        conn.close()
